export async function gotoInf(fileUri: Uri) {
        let locations: vscode.Location[] = [];

        let wps = await gEdkWorkspaces.getWorkspace(fileUri);
        if(wps.length){
            for (const wp of wps) {
                locations = await wp.getInfReference(fileUri);
                if(locations.length){
                    await vscode.commands.executeCommand('editor.action.goToLocations', vscode.window.activeTextEditor?.document.uri, vscode.window.activeTextEditor?.selection.active, locations, "gotoAndPeek", "Not found");
                }
            }
        }else{
            // Skip if source hasn't been indexed. Just make a search query
            let fileName = path.basename(fileUri.fsPath);
            let folderPath = path.dirname(fileUri.fsPath);

            let tempLocations = await rgSearch(`\\b${fileName}\\b`, ["*.inf"],[],true);
            for (const l of tempLocations) {
                // Check the INF file is relative to the source file
                if (!path.relative(path.dirname(l.uri.fsPath), folderPath).includes("..")) {
                    locations.push(l);
                }
            }
            await vscode.commands.executeCommand('editor.action.goToLocations', vscode.window.activeTextEditor?.document.uri, vscode.window.activeTextEditor?.selection.active, locations, "gotoAndPeek", "Not found");

        }

    }

async isFileInUse(uri: vscode.Uri) {

        if (this.processComplete) {
            
            switch (this.getLangId(uri)) {
                case "edk2_dsc":
                case "edk2_fdf":
                    // fdf files can be included in dsc files
                    for (const dsc of this.filesDsc) {
                        
                        if(uri.fsPath === dsc.fileName) {
                            return true;
                        }
                    }
                    
                    
                
                    for (const fdf of this.filesFdf) {
                        if(uri.fsPath === fdf.fileName){
                            return true;
                        }
                    }
                    return false;
                case "edk2_dec":
                    break;
                case "edk2_inf":
                    for (const mods of this.filesModules) {
                        if(uri.fsPath.includes(mods.path)){
                            return true;
                        }
                    }
                    for (const lib of this.filesLibraries) {
                        if(uri.fsPath.includes(lib.path)){
                            return true;
                        }
                    }
                    return false;
                    
                case "c":
                    let relativeInf:string[] = [];
                    let cDirName = path.dirname(uri.fsPath);
                    for (const mods of this.filesModules) {
                        let modDir = path.dirname(mods.path);
                        if(cDirName.includes(modDir)){
                            relativeInf.push(mods.path);
                        }
                    }
                    for (const lib of this.filesLibraries) {
                        let libDir = path.dirname(lib.path);
                        if(cDirName.includes(libDir)){
                            relativeInf.push(lib.path);
                        }
                    }
                    for (const inf of relativeInf) {
                        let infLocation = await gPathFind.findPath(inf);
                        
                        if (infLocation.length === 0){continue;}

                        let parser = await getParser(infLocation[0].uri);
                        if (parser) {
                            let sources = parser.getSymbolsType(Edk2SymbolType.infSource);
                            for (const source of sources) {
                                let sourceLocation = await gPathFind.findPath(await source.getValue(), path.dirname(infLocation[0].uri.fsPath));
                                if(sourceLocation[0].uri.fsPath === uri.fsPath){
                                    return true;
                                }
                            }
                        }
                    }
                    return false;
            }
        }
        return undefined;
    }

